import { useState, useEffect } from "react";

function useFetchBatters() {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<null | string>(null);
  const [data, setData] = useState([]);

  const fetchTopBatters = async (
    clearData: boolean,
    getTomorrow: boolean
  ) => {
    setIsLoading(true);
    const controller = new AbortController();
    const signal = controller.signal;

    try {
      console.log("in fetch data");
      const response = await fetch(
        `http://localhost:3001/api/scraper?clear=${clearData}&tomorrow=${getTomorrow}`,
        { signal }
      );
      if (!response.ok) {
        throw new Error("Failed to fetch data");
      }

      const data = await response.json();
      setData(data);
    } catch (err) {
      if (err.name === "AbortError") {
        console.log("Fetch aborted");
        return; // Exit early if the fetch was aborted
      }
      console.log("Error fetching top batters:", err);
      setError("Error fetching top batters");
    } finally {
      setIsLoading(false);
    }

    // Return the controller to allow the caller to abort the request if needed
    return controller;
  };

  useEffect(() => {
    const controller = fetchTopBatters(false, false);

    return () => {
      controller.abort(); // Cancel the request on component unmount
    };
  }, []);

  return { data, error, isLoading, refetch: fetchTopBatters };
}

export default useFetchBatters;
